total_size() {
  local dir="$1"
  local ext="$2"
  local bytes=$(find "$dir" -type f -name "*.$ext" -printf "%s\n" | awk '{total+=$1} END {print total}')
  printf "Total size: %.3f MB\n" "$(echo "scale=6; $bytes/1024/1024" | bc)"
}

git_rebase_and_push() {
  local branch=$1 prev=$(git rev-parse --abbrev-ref HEAD)
  git checkout "$branch" && git fetch origin && git rebase origin/main && make test && git push origin "$branch" || { git rebase --abort; git checkout "$prev"; }
}

command:
```bash
function create_zip() {
    local dir=$1
    local ext=$2
    local count=${3:-10}
    local timestamp=$(date +%Y%m%d%H%M%S)
    local zip_name="${dir}_${timestamp}.zip"

    find "$dir" -type f -name "*.$ext" -printf "%T+ %p\n" | sort -nr | head -n "$count" | xargs zip -r "$zip_name"
}
```

```bash
#!/bin/bash

# Rotate log files
find /var/log/myapp/ -name 'myapp.log.*' -mtime +1 -exec gzip {} \;
find /var/log/myapp/ -name 'myapp.log.*' -mtime +30 -exec rm {} \;

# Create a fresh myapp.log with correct permissions
touch /var/log/myapp/myapp.log
chmod 644 /var/log/myapp/myapp.log
```

```bash
create_thumbnails() {
    local dir="$1"
    mkdir -p "$dir/.thumbs"
    find "$dir" -type f -name "*.jpg" -size +5M -exec convert -resize 200x200 {} "$dir/.thumbs/{}.jpg" \;
    echo "Created thumbnails in $dir/.thumbs"
}
```

